### 3. Add the form logic

Do not also wire the button events in the Designer if using the constructor wiring below.

```csharp
using System;
using System.Windows.Forms;

namespace StudentMaintenance
{
    public partial class StudentForm : Form
    {
        public StudentForm()
        {
            InitializeComponent();

            Text = "Student Binary Data";
            StartPosition = FormStartPosition.CenterScreen;
            AcceptButton = btnWrite;

            btnWrite.Click += BtnWrite_Click;
            btnRead.Click += BtnRead_Click;
        }

        private bool IsValidData()
        {
            string id = txtStudentID.Text.Trim();
            string name = txtName.Text.Trim();
            string gpa = txtGPA.Text.Trim();

            string errors =
                Validator.IsPresent(id, "Student ID") +
                Validator.IsPresent(name, "Name") +
                Validator.IsPresent(gpa, "GPA");

            if (id.Length > 0)
                errors += Validator.IsPositiveInt32(id, "Student ID");

            if (gpa.Length > 0)
                errors += Validator.IsDecimalWithinRange(gpa, "GPA", 0, 4);

            if (errors.Length == 0)
                return true;

            MessageBox.Show(this, errors, "Invalid input",
                MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return false;
        }

        private void BtnWrite_Click(object? sender, EventArgs e)
        {
            if (!IsValidData())
                return;

            try
            {
                // If reading fails, execution goes directly to catch:
                // do not overwrite an unreadable file with an empty list.
                var students = StudentDB.GetStudents();

                students.Add(new Student
                {
                    StudentID = int.Parse(txtStudentID.Text.Trim()),
                    Name = txtName.Text.Trim(),
                    GPA = decimal.Parse(txtGPA.Text.Trim())
                });

                StudentDB.SaveStudents(students);

                MessageBox.Show(this, "Student saved.", "Write Data");

                // Preserve the user's inputs if saving fails.
                txtStudentID.Clear();
                txtName.Clear();
                txtGPA.Clear();
                txtStudentID.Focus();
            }
            catch (Exception ex)
            {
                // UI boundary: report the failure rather than continuing.
                MessageBox.Show(this, $"Unable to save:\n{ex.Message}",
                    "File error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void BtnRead_Click(object? sender, EventArgs e)
        {
            try
            {
                var students = StudentDB.GetStudents();

                lstStudents.Items.Clear();
                foreach (Student student in students)
                    lstStudents.Items.Add(student);

                if (students.Count == 0)
                    MessageBox.Show(this, "No saved students.", "Read Data");
            }
            catch (Exception ex)
            {
                MessageBox.Show(this, $"Unable to read:\n{ex.Message}",
                    "File error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
    }
}
```

