    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        dsu.unite(u, v);
    }

    vector<int> best(n + 1, -1);
    for (int v = 1; v <= n; ++v) {
        int r = dsu.find(v);
        if (best[r] == -1 || a[v] < a[best[r]]) {
            best[r] = v;
        }
    }

    int root = dsu.find(s);
    vector<pair<int, int>> roads;

    for (int r = 1; r <= n; ++r) {
        if (best[r] != -1 && r != root) {
            roads.emplace_back(s, best[r]);
        }
    }

    cout << roads.size() << '\n';
    for (auto [u, v] : roads) {
        cout << u << ' ' << v << '\n';
    }
}
```

