            ui.horizontal(|ui| {
                if ui.add_enabled(!running, egui::Button::new("Start")).clicked() {
                    self.start(ctx);
                }

                if ui.add_enabled(running, egui::Button::new("Stop")).clicked() {
                    self.watcher = None;
                    self.receiver = None;
