(() => {
  const $ = id => document.getElementById(id);
  const editor = $("editor"), paint = $("paint");
  const key = "pocket-notepad-v1";
  let size = 15, timer;

  const escape = s => s.replace(/[&<>]/g,
    c => ({"&":"&amp;","<":"&lt;",">":"&gt;"}[c]));

  function highlight(text) {
    if ($("lang").value === "text") return escape(text);
    // Tokenize source before generating markup; never reprocess generated HTML.
    const re = $("lang").value === "json"
      ? /("(?:\\.|[^"\\])*")|\b(true|false|null)\b|(-?\b\d+(?:\.\d+)?(?:e[+-]?\d+)?)/gi
