    let html = "", last = 0;
    for (const m of text.matchAll(re)) {
      html += escape(text.slice(last, m.index));
      const index = m.slice(1).findIndex(v => v !== undefined);
      const cls = ($("lang").value === "json"
        ? ["s","k","n"] : ["c","s","k","n"])[index];
      html += `<span class="${cls}">${escape(m[0])}</span>`;
      last = m.index + m[0].length;
    }
    return html + escape(text.slice(last));
  }

  function sync() {
    paint.style.transform =
      `translate(${-editor.scrollLeft}px,${-editor.scrollTop}px)`;
  }
  function fit() {
    if ($("stack").classList.contains("wrap"))
