  }
  function stats() {
    const value = editor.value, pos = editor.selectionStart;
    const before = value.slice(0, pos);
    $("stats").textContent =
      `${value.split("\n").length} lines · ${value.length} chars · ` +
      `${(value.match(/\S+/g)||[]).length} words · ` +
      `Ln ${before.split("\n").length}, Col ${pos-before.lastIndexOf("\n")}`;
  }
  function render() {
    paint.innerHTML = highlight(editor.value) + "\n";
    fit(); sync(); stats();
  }
  function persist() {
    clearTimeout(timer);
    try {
      localStorage.setItem(key, JSON.stringify({
        text:editor.value,name:$("name").value,lang:$("lang").value,
        light:document.body.classList.contains("light"),size
      }));
      $("notice").textContent = "Saved in this browser";
    } catch {
      $("notice").textContent = "Storage unavailable — download a backup";
    }
  }
  function changed() {
    render();
    $("notice").textContent = "Saving…";
