    editor.setRangeText(value,editor.selectionStart,
      editor.selectionEnd,"end");
    changed(); editor.focus();
  }

  try {
    const saved = JSON.parse(localStorage.getItem(key) || "null");
    if (saved && typeof saved.text === "string") {
      editor.value = saved.text;
      $("name").value = saved.name || "note.txt";
      $("lang").value = ["js","json","text"].includes(saved.lang)
        ? saved.lang : "text";
      document.body.classList.toggle("light", !!saved.light);
      size = Math.max(10,Math.min(30,Number(saved.size)||15));
    }
  } catch {
    $("notice").textContent = "Could not restore browser storage";
  }

  $("new").onclick = () => {
    if (editor.value && !confirm("Clear this note? Download a copy first.")) return;
    editor.value = ""; $("name").value = "untitled.txt";
    changed(); editor.focus();
  };
  $("open").onclick = () => $("file").click();
  $("file").onchange = async () => {
    const file = $("file").files[0];
    if (!file) return;
    if (editor.value && !confirm("Replace this note with the selected file?")) {
      $("file").value = ""; return;
    }
    try {
