## My answer to the prompt

I would highlight **double-quoted text**, including straight quotes (`"..."`) and curly quotes (`“...”`). Curly quotes matter because your code enables Marked’s `smartypants` option.

The implementation below preserves Markdown formatting inside quotes, leaves code blocks alone, and changes only `MarkdownBlock`. Should single-quoted text (`'...'`) also count? That requires distinguishing quotation marks from apostrophes.

Add this CSS:

```css
md-block .md-quoted {
	color: red;
}
```

Add this helper outside the classes:

```js
function highlightQuotedText(root) {
	const boundaries = new Set([
		"ADDRESS", "ARTICLE", "ASIDE", "BLOCKQUOTE", "DIV",
		"DL", "DT", "DD", "FIGURE", "FIGCAPTION", "FOOTER",
		"H1", "H2", "H3", "H4", "H5", "H6", "HEADER",
		"HR", "LI", "MAIN", "NAV", "OL", "P", "SECTION",
		"TABLE", "TBODY", "TD", "TH", "THEAD", "TFOOT",
		"TR", "UL"
	]);

	const excluded = new Set([
		"CODE", "PRE", "SCRIPT", "STYLE", "TEXTAREA"
	]);

	let nodes = [];

	function flush() {
		if (!nodes.length) return;

		const text = nodes.map(node => node.data).join("");
		const matches = Array.from(
			text.matchAll(/"[^"]+"|“[^”]+”/g),
			match => ({
				start: match.index,
				end: match.index + match[0].length
			})
		);

		let offset = 0;

		for (const node of nodes) {
			const value = node.data;
			const end = offset + value.length;
			const fragment = document.createDocumentFragment();
			let cursor = 0;

			for (const match of matches) {
				if (match.end <= offset || match.start >= end) continue;

				const from = Math.max(match.start, offset) - offset;
				const to = Math.min(match.end, end) - offset;

				fragment.append(document.createTextNode(
					value.slice(cursor, from)
				));

				const span = document.createElement("span");
				span.className = "md-quoted";
				span.textContent = value.slice(from, to);
				fragment.append(span);
				cursor = to;
			}

			if (cursor > 0) {
				fragment.append(document.createTextNode(value.slice(cursor)));
				node.replaceWith(fragment);
			}

			offset = end;
		}

		nodes = [];
	}

	function visit(node) {
		if (node.nodeType === Node.TEXT_NODE) {
			nodes.push(node);
			return;
		}

		const tag = node.nodeType === Node.ELEMENT_NODE
			? node.tagName
			: "";

		if (excluded.has(tag) || tag === "BR") {
			flush();
			return;
		}

		const boundary = boundaries.has(tag);
		if (boundary) flush();

		// Snapshot the children because flush() can replace text nodes.
		for (const child of Array.from(node.childNodes)) {
			visit(child);
		}

		if (boundary) flush();
	}

	visit(root);
	flush();
}
```

Replace **only `MarkdownBlock._parse()`** with:

```js
_parse() {
	const template = document.createElement("template");
	template.innerHTML = marked.parse(this._mdContent);

	highlightQuotedText(template.content);

	return template.innerHTML;
}
```

Your existing sanitization still runs afterward. This highlights the quotation marks and their contents, including `"some **bold** text"`, without changing HTML attributes. Matches deliberately do not cross separate blocks, explicit line breaks, or excluded code elements.

Also, the posted source has missing template-literal backticks. Correct those expressions, for example:

