```js
_parse() {
	const template = document.createElement("template");
	template.innerHTML = marked.parse(this._mdContent);

	const skip = new Set([
		"CODE", "PRE", "SCRIPT", "STYLE", "TEXTAREA"
	]);

	const boundaries = new Set([
		"ADDRESS", "ARTICLE", "ASIDE", "BLOCKQUOTE", "DIV",
		"DL", "DT", "DD", "FIGURE", "FIGCAPTION", "FOOTER",
		"H1", "H2", "H3", "H4", "H5", "H6", "HEADER",
		"HR", "LI", "MAIN", "NAV", "OL", "P", "SECTION",
		"TABLE", "TBODY", "TD", "TH", "THEAD", "TR", "UL"
	]);

	let text = "";
	const nodes = [];

	function collect(node) {
		if (node.nodeType === Node.TEXT_NODE) {
			const start = text.length;
			text += node.data;
			nodes.push({ node, start, end: text.length });
			return;
		}

		if (skip.has(node.nodeName) || node.nodeName === "BR") {
			text += "\0";
			return;
		}

		const boundary = boundaries.has(node.nodeName);
		if (boundary) text += "\0";

		for (const child of node.childNodes) collect(child);

		if (boundary) text += "\0";
	}

	collect(template.content);

	const matches = [...text.matchAll(/"[^"\0]+"|“[^”\0]+”/g)]
		.map(match => ({
			start: match.index,
			end: match.index + match[0].length
		}));

	for (const { node, start, end } of nodes) {
		const overlapping = matches.filter(
			match => match.start < end && match.end > start
		);

		if (!overlapping.length) continue;

		const fragment = document.createDocumentFragment();
		let cursor = 0;

		for (const match of overlapping) {
			const from = Math.max(start, match.start) - start;
			const to = Math.min(end, match.end) - start;

			fragment.append(document.createTextNode(
				node.data.slice(cursor, from)
			));

			const span = document.createElement("span");
			span.className = "md-quoted";
			span.textContent = node.data.slice(from, to);
			fragment.append(span);

			cursor = to;
		}

		fragment.append(document.createTextNode(node.data.slice(cursor)));
		node.replaceWith(fragment);
	}

	return template.innerHTML;
}
```

This processes rendered text, not HTML attributes, and handles quotes spanning inline formatting—for example, `"some **bold** text"`. Existing sanitization still runs afterward. Curly quotes matter because your configuration enables `smartypants`.

