The essential search and validation logic would be:

```tsx
type Entry = { label: string; key: string };

const normalize = (value: string) =>
  value.trim().normalize("NFKC").toLowerCase();

function buildIndex(options: readonly string[]) {
  const unique = new Map<string, string>();

  for (const label of options) {
    const key = normalize(label);
    if (key && !unique.has(key)) unique.set(key, label);
  }

  const entries: Entry[] = [...unique].map(([key, label]) => ({
    key,
    label,
  }));

  entries.sort((a, b) =>
    a.key < b.key ? -1 : a.key > b.key ? 1 : 0,
  );

  return { entries, keys: new Set(unique.keys()) };
}

function lowerBound(
  entries: readonly Entry[],
  predicate: (entry: Entry) => boolean,
) {
  let low = 0;
  let high = entries.length;

  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);
    if (predicate(entries[middle])) high = middle;
    else low = middle + 1;
  }

  return low;
}

function prefixRange(
  entries: readonly Entry[],
  query: string,
): [number, number] {
  if (!query) return [0, 0];

  const start = lowerBound(entries, entry => entry.key >= query);
  const end = lowerBound(
    entries,
    entry => entry.key >= query && !entry.key.startsWith(query),
  );

  return [start, end];
}

function validateValue(
  value: string,
  keys: ReadonlySet<string>,
  required: boolean,
): string | null {
  const key = normalize(value);

  if (!key) return required ? "This field is required." : null;
  return keys.has(key) ? null : "Choose an available option.";
}
```

Inside the component, memoize `buildIndex(options)` and search the resulting index for the current normalized value. Render the matching range through a virtualizer such as `@tanstack/react-virtual`; do not copy or render the entire matching range.

Dropdown visibility should be explicitly derived:

```tsx
const visible =
  open && focused && !disabled && !readOnly && !composing && matchCount > 0;
```

Selecting an option should update the controlled value, close the dropdown, clear the highlighted index, and retain or restore input focus. Escape and leaving the component should close it; Tab should retain its normal navigation behavior. Enter should prevent form submission **only when selecting a highlighted suggestion**.

For validation, derive the error on every relevant value/options change, display an associated error message and red border after interaction, and use `setCustomValidity` plus `onInvalid` if native form submission must enforce membership.

Use combobox/listbox semantics, an accessible label, `aria-expanded`, and `aria-activedescendant`. With virtualization, ensure the active descendant stays mounted and scroll it into view.

Important tests include empty and duplicate options, whitespace, no matches, dynamically changing options, externally updated values, keyboard selection, touch scrolling, blur during selection, IME input, and form submission. For millions of options, move indexing/searching to a worker or server; virtualization alone does not eliminate data-loading and indexing costs.

