const desktop = document.querySelector("#desktop");
const taskbar = document.querySelector("#taskbar");
const storageKey = "simple-desktop-files";
let files = [{ name: "Welcome.txt", content: "Welcome! Edit this file and save." }];
let z = 1;
const editors = new Set();

