Yes. A good approach is to make the chart an **`Fl_Widget`** that can be placed inside an `Fl_Window`. Keep each graph’s points and drawing style separate from the shared axes and grid.

Here is a possible header. It declares the interface; the drawing and data-management methods still need a `.cpp` implementation.

```cpp
#ifndef CHART_2D_H
#define CHART_2D_H

#include <FL/Fl_Widget.H>
#include <FL/fl_draw.H>

#include <cstddef>
#include <cstdint>
#include <iosfwd>
#include <string>
#include <vector>

class Chart2D : public Fl_Widget {
public:
    struct Point {
        float x;
        float y;
    };

    using Points = std::vector<Point>;
    using GraphId = std::uint64_t;

    enum class GraphType { Lines, Points, LinesAndPoints };

    struct GraphStyle {
        GraphType type = GraphType::Lines;
        Fl_Color color = FL_BLUE;
        int line_style = FL_SOLID;
        int line_width = 1;
        int point_radius = 3;
    };

    struct Axis {
        std::string name;
        float minimum = 0.0f;
        float maximum = 1.0f;
    };

    struct Grid {
        bool vertical = true;
        bool horizontal = true;
        float x_step = 1.0f; // Positive spacing in data units
        float y_step = 1.0f;
        Fl_Color color = FL_LIGHT2;
        int line_style = FL_DOT;
        int line_width = 1;
    };

    Chart2D(int x, int y, int width, int height,
            const char* label = nullptr);
    ~Chart2D() override = default;

    Chart2D(const Chart2D&) = delete;
    Chart2D& operator=(const Chart2D&) = delete;

    // IDs are stable and are not reused during this object's lifetime.
    GraphId add_graph(std::string name);
    GraphId add_graph(std::string name, const GraphStyle& style);
    bool remove_graph(GraphId id);
    bool rename_graph(GraphId id, std::string name);
    bool set_graph_style(GraphId id, const GraphStyle& style);
    void clear_graphs();

    // Return false for unknown graph IDs or invalid point indices.
    bool add_point(GraphId id, Point point);
    bool add_points(GraphId id, const Points& points);
    bool remove_point(GraphId id, std::size_t index);
    bool clear_points(GraphId id);

    // Change axis names and displayed coordinate ranges.
    void set_x_axis(const Axis& axis);
    void set_y_axis(const Axis& axis);
    void set_grid(const Grid& grid);

    // Change the widget's pixel dimensions, not its coordinate ranges.
    void resize(int x, int y, int width, int height) override;

    void print_info(std::ostream& output) const;

protected:
    void draw() override;

private:
    struct Graph {
        GraphId id;
        std::string name;
        Points points;
        GraphStyle style;
    };

    Graph* find_graph(GraphId id);

    void draw_grid() const;
    void draw_graphs() const;
    void draw_axes() const;

    std::vector<Graph> graphs_;
    GraphId next_id_ = 1;

    Axis x_axis_{"X", 0.0f, 1.0f};
    Axis y_axis_{"Y", 0.0f, 1.0f};
    Grid grid_;
};

#endif
```

`std::vector<Point>` serves as the requested collection of points and is generally suitable for sequential chart drawing. Use `std::list<Point>` only if you specifically need linked-list behavior.

