Should the sum be allowed to exceed `b`, or must it stay within budget?

If “closest” means the smallest absolute difference from `b`, allowing sums above it, use this function. It selects **one integer from each array**, favors the smaller sum on ties, and returns `null` if either array is empty.

```js
function getExpense(arr1, arr2, b) {
  let best = null;

  for (const x of arr1) {
    for (const y of arr2) {
      const sum = x + y;

      if (
        best === null ||
        Math.abs(sum - b) < Math.abs(best - b) ||
        (Math.abs(sum - b) === Math.abs(best - b) && sum < best)
      ) {
        best = sum;
      }

      if (best === b) return best;
    }
  }

  return best;
}

console.log(getExpense([3, 7, 10], [2, 6, 9], 15)); // 16
