Here is a basic smooth-surface controller for Unity 2023:

```csharp
using UnityEngine;

[RequireComponent(typeof(Rigidbody), typeof(CapsuleCollider))]
public class SurfaceWalker : MonoBehaviour
{
    public LayerMask walkable;
    public float speed = 4f;
    public float gravity = 30f;
    public float turnSpeed = 12f;
    public float probeDistance = 2f; // From capsule center.

    Rigidbody rb;
    Vector2 input;
    Vector3 surfaceUp;

    void Awake()
    {
        rb = GetComponent<Rigidbody>();
        rb.useGravity = false;
        rb.freezeRotation = true;
        rb.interpolation = RigidbodyInterpolation.Interpolate;

        surfaceUp = transform.up;
    }

    void Update()
    {
        input = Vector2.ClampMagnitude(new Vector2(
            Input.GetAxisRaw("Horizontal"),
            Input.GetAxisRaw("Vertical")), 1f);
    }

    void FixedUpdate()
    {
        if (Physics.Raycast(
            rb.worldCenterOfMass, -surfaceUp,
            out RaycastHit hit, probeDistance,
            walkable, QueryTriggerInteraction.Ignore))
        {
            surfaceUp = hit.normal.normalized;

            // Transport the character's orientation onto the new surface.
            Quaternion aligned =
                Quaternion.FromToRotation(
                    rb.rotation * Vector3.up, surfaceUp)
                * rb.rotation;

            Vector3 forward = aligned * Vector3.forward;
            Vector3 right = aligned * Vector3.right;

            Vector3 tangentVelocity =
                (forward * input.y + right * input.x) * speed;

            rb.velocity =
                tangentVelocity + Vector3.Project(rb.velocity, surfaceUp);

            rb.MoveRotation(Quaternion.Slerp(
                rb.rotation, aligned,
                1f - Mathf.Exp(-turnSpeed * Time.fixedDeltaTime)));
        }

        // Continue using the last surface direction if the probe misses.
        rb.AddForce(-surfaceUp * gravity, ForceMode.Acceleration);
    }
}
```

This uses the classic Input Manager; enable **Input Manager (Old)** or **Both** under Active Input Handling. Start the player just above the surface, with its up axis approximately aligned to the surface normal. Set the probe distance slightly longer than half the capsule height.

**For cube edges and complex meshes:** extend the controller with forward and around-edge probes. When an adjacent face is found, validate capsule clearance and transition the character around the edge while maintaining its surface offset. Use a short-lived surface lock or hysteresis to prevent rapid switching between competing faces. Beveled edges make this much easier.

