```cpp
#include <iostream>
#include <cstring>
using namespace std;

int main() {
    char a[105];
    int num[105];
    int b;

    cin >> a >> b;

    int n = strlen(a);

    // 把每个数字字符转换成整数，存入 int 数组
    for (int i = 0; i < n; i++) {
        num[i] = a[i] - '0';
    }

    int carry = b;

    // 从个位向最高位依次计算
    for (int i = n - 1; i >= 0; i--) {
        int sum = num[i] + carry;

        if (sum >= 10) {
            num[i] = sum - 10;
            carry = 1;
        } else {
            num[i] = sum;
            carry = 0;
        }
    }

    if (carry == 1) {
        cout << 1;
    }

    for (int i = 0; i < n; i++) {
        cout << num[i];
    }
    cout << '\n';

    return 0;
}
```

