### 3. Drive the process with step definitions

```javascript
const definitions = [
    ["nameStep", "Enter your name, using at least two characters."],
    ["emailStep", "Enter a valid email address, then select Next."],
    ["passwordStep", "Choose a password of at least 12 characters."]
];

const steps = definitions.map(([id, help]) => {
    const container = document.getElementById(id);
    return { container, input: container.querySelector("input"), help };
});

const form = document.getElementById("registration");
const back = document.getElementById("back");
const next = document.getElementById("next");
const instructions = document.getElementById("instructions");
let current = 0;

function showStep(index) {
    current = index;

    steps.forEach((step, i) => {
        const active = i === current;
        step.container.disabled = !active;
        step.container.inert = !active;
        step.container.classList.toggle("active", active);
    });

    instructions.textContent =
        `Step ${current + 1} of ${steps.length}: ${steps[current].help}`;

    back.disabled = current === 0;
    next.textContent =
        current === steps.length - 1 ? "Create account" : "Next";

    steps[current].input.focus();
}

back.addEventListener("click", () => {
    if (current > 0) showStep(current - 1);
});

form.addEventListener("submit", event => {
    event.preventDefault();

    if (!steps[current].input.reportValidity()) return;

    if (current < steps.length - 1) {
        showStep(current + 1);
        return;
    }

    // Implement submission and display server validation errors.
    submitRegistration(collectData());
});

function collectData() {
    // Disabled fields are excluded from FormData.
    const previous = steps.map(step => step.container.disabled);

    try {
        steps.forEach(step => step.container.disabled = false);
        return new FormData(form);
    } finally {
        steps.forEach((step, i) => {
            step.container.disabled = previous[i];
        });
    }
}

showStep(0);
```

`submitRegistration` should POST using `fetch`, disable navigation while submitting, handle failures, and return to the field identified by server validation errors. The generated antiforgery token is included in `FormData`.

### 4. Handle registration securely in ASP.NET Core

On the server:

1. Bind a registration DTO with explicit validation attributes.
2. Reject invalid `ModelState`.
3. Create the account using `UserManager<ApplicationUser>.CreateAsync(user, password)`.
4. Return field-specific validation errors or a success response.

Use ASP.NET Core Identity rather than storing passwords yourself. Keep its password policy consistent with the displayed instructions. Add email confirmation and registration rate limiting for production.

For reuse, extract the JavaScript into a `GuidedProcess` component that accepts step definitions, validation callbacks, and a completion callback. A persistent workflow engine is only necessary if the process needs features such as saved progress or approvals.

