Assuming you mean Kubernetes application resources in an existing cluster, I would run Home Assistant and nginx in one Pod, with nginx acting as a reverse proxy. Home Assistant needs persistent storage, and its configuration must explicitly trust the local proxy.

The following CUE separates settings, application configuration, and Kubernetes resources:

```cue
package cluster

// User-adjustable settings.
settings: {
	name:     "home-assistant"
	timezone: "Etc/UTC"

	// Pin tested versions or digests for reproducible deployments.
	images: {
		homeAssistant: "ghcr.io/home-assistant/home-assistant:stable"
		nginx:         "nginx:stable-alpine"
	}

	storageSize: "10Gi"
}

let cfg = settings
let labels = {app: cfg.name}
let configName = "\(cfg.name)-config"
let storageName = "\(cfg.name)-data"

// Reusable metadata. Resources use the namespace selected by kubectl.
#Metadata: {
	name:   string
	labels: labels
}

configuration: {
	homeAssistant: """
		default_config:
		homeassistant:
		  time_zone: "\(cfg.timezone)"
		http:
		  use_x_forwarded_for: true
		  trusted_proxies:
		    - 127.0.0.1
		"""

	// Mounted into the stock image's conf.d directory.
	nginx: """
		map $http_upgrade $connection_upgrade {
		    default upgrade;
		    ''      close;
		}

		server {
		    listen 80;
		    server_name _;

		    location / {
		        proxy_pass http://127.0.0.1:8123;
		        proxy_http_version 1.1;

		        proxy_set_header Host $http_host;
		        proxy_set_header X-Real-IP $remote_addr;
		        proxy_set_header X-Forwarded-For $remote_addr;
		        proxy_set_header X-Forwarded-Proto $scheme;
		        proxy_set_header Upgrade $http_upgrade;
		        proxy_set_header Connection $connection_upgrade;

		        proxy_buffering off;
		        proxy_read_timeout 3600s;
		    }
		}
		"""
}

resources: {
	config: {
		apiVersion: "v1"
		kind:       "ConfigMap"
		metadata: #Metadata & {name: configName}
		data: {
			"configuration.yaml": configuration.homeAssistant
			"default.conf":       configuration.nginx
		}
	}

	storage: {
		apiVersion: "v1"
		kind:       "PersistentVolumeClaim"
		metadata: #Metadata & {name: storageName}
		spec: {
			accessModes: ["ReadWriteOnce"]
			resources: requests: storage: cfg.storageSize
		}
	}

	deployment: {
		apiVersion: "apps/v1"
		kind:       "Deployment"
		metadata: #Metadata & {name: cfg.name}
		spec: {
			replicas: 1
			// Avoid concurrent instances writing the same local database.
			strategy: type: "Recreate"
			selector: matchLabels: labels

			template: {
				metadata: labels: labels
				spec: {
					automountServiceAccountToken: false

					containers: [
						{
							name:  "home-assistant"
							image: cfg.images.homeAssistant
							env: [{name: "TZ", value: cfg.timezone}]
							ports: [{
								name:          "ha-http"
								containerPort: 8123
							}]
							volumeMounts: [
								{name: "data", mountPath: "/config"},
								{
									name:      "configuration"
									mountPath: "/config/configuration.yaml"
									subPath:   "configuration.yaml"
									readOnly:  true
								},
							]
							startupProbe: {
								httpGet: {path: "/", port: "ha-http"}
								periodSeconds:    10
								failureThreshold: 60
							}
							readinessProbe: {
								httpGet: {path: "/", port: "ha-http"}
								periodSeconds: 10
							}
						},
						{
							name:  "nginx"
							image: cfg.images.nginx
							ports: [{
								name:          "http"
								containerPort: 80
							}]
							volumeMounts: [{
								name:      "configuration"
								mountPath: "/etc/nginx/conf.d/default.conf"
								subPath:   "default.conf"
								readOnly:  true
							}]
							readinessProbe: {
								tcpSocket: port: "http"
								periodSeconds: 10
							}
						},
					]

					volumes: [
						{
							name: "data"
							persistentVolumeClaim: claimName: storageName
						},
