## 我的解答

使用**扫描线 + 线段树**。

将每个矩形转换为两个事件：在左边界加入纵向区间，在右边界删除纵向区间。将纵坐标离散化后，用线段树维护当前被覆盖的纵向总长度。

处理横坐标为 `x` 的事件前，先累加：
\[
\text{新增面积}=(x-\text{上一个事件的横坐标})\times\text{当前纵向覆盖长度}
\]

线段树维护覆盖计数和覆盖长度：计数大于零时，该节点对应区间全部被覆盖；否则，非叶节点的覆盖长度为两个子节点之和，叶节点的覆盖长度为零。

```cpp
#include <bits/stdc++.h>
using namespace std;

using ll = long long;
constexpr ll MOD = 1000000007LL;

struct Event {
    ll x, y1, y2;
    int delta;
};

vector<ll> ys, len;
vector<int> cover;

// 节点表示基本区间下标 [l, r]
void update(int p, int l, int r, int ql, int qr, int delta) {
    if (qr < l || r < ql) return;

    if (ql <= l && r <= qr) {
        cover[p] += delta;
    } else {
        int mid = (l + r) / 2;
        update(p * 2, l, mid, ql, qr, delta);
        update(p * 2 + 1, mid + 1, r, ql, qr, delta);
    }

    if (cover[p] > 0) {
        len[p] = ys[r + 1] - ys[l];
    } else if (l == r) {
        len[p] = 0;
    } else {
        len[p] = len[p * 2] + len[p * 2 + 1];
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Event> events;
    for (int i = 0; i < n; ++i) {
        ll x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;

        if (x1 == x2 || y1 == y2) continue;

        events.push_back({x1, y1, y2, 1});
        events.push_back({x2, y1, y2, -1});
        ys.push_back(y1);
        ys.push_back(y2);
    }

    if (events.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    sort(events.begin(), events.end(),
         [](const Event& a, const Event& b) {
             return a.x < b.x;
         });

    int m = static_cast<int>(ys.size()) - 1;
    cover.assign(4 * m + 4, 0);
    len.assign(4 * m + 4, 0);

    ll answer = 0;
    ll previousX = events.front().x;

    for (const Event& e : events) {
        answer = (answer + len[1] * (e.x - previousX) % MOD) % MOD;

        int l = lower_bound(ys.begin(), ys.end(), e.y1) - ys.begin();
        int r = lower_bound(ys.begin(), ys.end(), e.y2) - ys.begin();
        update(1, 0, m - 1, l, r - 1, e.delta);

        previousX = e.x;
    }

    cout << answer << '\n';
    return 0;
}
```

- 时间复杂度：\(O(n\log n)\)。
- 空间复杂度：\(O(n)\)。
- 坐标不超过 \(10^9\)，单次面积乘积不超过 \(10^{18}\)，使用 `long long` 安全。
- 相同横坐标的事件之间宽度为零，因此可以逐个处理，不必特别规定加入和删除的先后顺序。

