const ll MOD = 1000000007LL;

struct Event {
    ll x, y1, y2;
    int delta;
};

vector<ll> ys, covered;
vector<int> cnt;

// 节点 [l, r] 对应实际区间 [ys[l], ys[r + 1])
void pull(int p, int l, int r) {
    if (cnt[p] > 0)
        covered[p] = ys[r + 1] - ys[l];
    else if (l == r)
        covered[p] = 0;
    else
        covered[p] = covered[p * 2] + covered[p * 2 + 1];
}

void update(int p, int l, int r, int ql, int qr, int delta) {
    if (qr < l || r < ql) return;

    if (ql <= l && r <= qr) {
        cnt[p] += delta;
    } else {
        int mid = (l + r) / 2;
        update(p * 2, l, mid, ql, qr, delta);
        update(p * 2 + 1, mid + 1, r, ql, qr, delta);
    }
    pull(p, l, r);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Event> events;
    for (int i = 0; i < n; ++i) {
        ll x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;

        if (x1 == x2 || y1 == y2) continue;

        events.push_back({x1, y1, y2, 1});
        events.push_back({x2, y1, y2, -1});
        ys.push_back(y1);
        ys.push_back(y2);
    }

    if (events.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    sort(events.begin(), events.end(),
         [](const Event& a, const Event& b) {
             return a.x < b.x;
         });

    int m = static_cast<int>(ys.size()) - 1;
    cnt.assign(4 * m + 4, 0);
    covered.assign(4 * m + 4, 0);

    ll ans = 0;
    ll previousX = events.front().x;

    for (const auto& e : events) {
        ans = (ans + covered[1] * (e.x - previousX) % MOD) % MOD;

        int l = lower_bound(ys.begin(), ys.end(), e.y1) - ys.begin();
        int r = lower_bound(ys.begin(), ys.end(), e.y2) - ys.begin();
        update(1, 0, m - 1, l, r - 1, e.delta);

        previousX = e.x;
    }

    cout << ans << '\n';
    return 0;
}
```

**复杂度：**时间 \(O(n\log n)\)，空间 \(O(n)\)。

相同横坐标的事件之间宽度为零，因此可以逐个处理，不必专门分组。坐标上限为 \(10^9\)，一次面积乘积不超过 \(10^{18}\)，使用 `long long` 安全。

## 对两份回答的评价

### Assistant A

- **正确性：**与我的答案一致，扫描顺序、离散化区间映射、线段树维护及取模计算均正确。
- **边界处理：**明确跳过零面积矩形，并在没有有效事件时输出 `0`，处理比较稳健。
- **表达：**思路、代码、复杂度层次清楚，使用了规范的 C++ 代码块。
- **可补充信息：**可以简要解释相同横坐标事件为什么不需要特殊排序，以及 `long long` 为什么不会溢出，但这不影响答案正确性。

### Assistant B

- **主要算法正确：**对于满足 `x1 < x2`、`y1 < y2` 的非退化矩形，代码能够正确计算并集面积。其半开区间线段树实现与我的答案只是下标约定不同。
- **存在边界问题：**题面没有明确给出严格不等式，因此应考虑零面积矩形。例如：
  ```text
  1
  0 0 1 0
  ```
  正确答案是 `0`。但 B 的纵坐标去重后只有一个元素，导致 `seg.n == 0`、`seg.len` 为空，随后访问 `seg.len[1]`，产生越界和未定义行为。

  **修正方法：**读入时跳过宽或高为零的矩形，并在事件为空时直接输出 `0`。这两项检查需要一起添加。
- **表达与简洁性：**代码前后重复介绍扫描流程；使用分隔线而非代码块，可读性逊于 A。
- **遗漏：**没有给出时间和空间复杂度，应补充 \(O(n\log n)\) 和 \(O(n)\)。

## 综合判断

两份回答都选用了符合“线段树”章节要求的标准算法，没有需要特别评价的创意差异。题意足以直接作答，不需要额外澄清；对于未明确排除的退化矩形，防御性处理更合适。

A 在常规输入上与 B 同样正确，但边界处理更完整，格式更规范，说明也更精炼。B 的主要算法并无根本性错误，因此整体差距有限。

