## My answer to the prompt

Assuming **Unity’s Built-in Render Pipeline**, I would interpret “extrude” as turning each nontransparent texel into a small box, extending along object-space **+Z**. The extrusion factor multiplies the pixel’s object-space size.

A practical geometry-shader implementation uses **one input point per texture texel**. The shader samples that texel at mip level 0, skips it if transparent, and emits six faces otherwise.

### Shader

```hlsl
Shader "Custom/ExtrudedTexturePixels"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _PixelSize ("Pixel Size", Float) = 0.01
        _Extrusion ("Extrusion Factor", Float) = 1
        _AlphaCutoff ("Alpha Cutoff", Range(0,1)) = 0
    }

    SubShader
    {
        Tags { "RenderType"="Opaque" }

        Pass
        {
            Cull Back
            ZWrite On

            CGPROGRAM
            #pragma target 4.0
            #pragma vertex Vert
            #pragma geometry Geom
            #pragma fragment Frag
            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _PixelSize;
            float _Extrusion;
            float _AlphaCutoff;

            struct Input
            {
                float4 position : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct PointData
            {
                float4 position : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct RasterData
            {
                float4 position : SV_POSITION;
                float4 color : COLOR0;
            };

            PointData Vert(Input v)
            {
                PointData o;
                o.position = v.position; // Keep object-space coordinates.
                o.uv = v.uv;
                return o;
            }

            void Emit(float3 p, float4 color,
                      inout TriangleStream<RasterData> stream)
            {
                RasterData o;
                o.position = UnityObjectToClipPos(float4(p, 1));
                o.color = color;
                stream.Append(o);
            }

            // Corners supplied in perimeter order.
            void Face(float3 a, float3 b, float3 c, float3 d,
                      float4 color,
                      inout TriangleStream<RasterData> stream)
            {
                Emit(a, color, stream);
                Emit(b, color, stream);
                Emit(d, color, stream);
                Emit(c, color, stream);
                stream.RestartStrip();
            }

            [maxvertexcount(24)]
            void Geom(point PointData input[1],
                      inout TriangleStream<RasterData> stream)
            {
                // Geometry shaders have no implicit texture derivatives.
                float4 color =
                    tex2Dlod(_MainTex, float4(input[0].uv, 0, 0));

                if (color.a <= _AlphaCutoff)
                    return;

                // Transparency is used as a mask, not alpha blending.
                color.a = 1;

                float3 p = input[0].position.xyz;
                float h = _PixelSize * 0.5;
                float depth = _PixelSize * max(0.0, _Extrusion);

                float3 a = p + float3(-h, -h, 0);
                float3 b = p + float3( h, -h, 0);
                float3 c = p + float3( h,  h, 0);
                float3 d = p + float3(-h,  h, 0);

                if (depth <= 0)
                {
                    Face(a, b, c, d, color, stream);
                    Face(b, a, d, c, color, stream);
                    return;
                }

                float3 z = float3(0, 0, depth);

                Face(a + z, b + z, c + z, d + z, color, stream);
                Face(b, a, d, c, color, stream);
                Face(a, b, b + z, a + z, color, stream);
                Face(d, d + z, c + z, c, color, stream);
                Face(a, a + z, d + z, d, color, stream);
                Face(b, c, c + z, b + z, color, stream);
            }

            float4 Frag(RasterData input) : SV_Target
            {
                return input.color;
            }
            ENDCG
        }
    }
}
```

### Input mesh

Use this helper inside a C# component to create the point mesh:

```csharp
using UnityEngine;
using UnityEngine.Rendering;

public static class PixelPointMesh
{
    public static Mesh Create(
        Texture2D texture, float pixelSize, float extrusion)
    {
        int width = texture.width;
        int height = texture.height;
        int count = checked(width * height);

        var vertices = new Vector3[count];
        var uvs = new Vector2[count];
        var indices = new int[count];

        for (int y = 0; y < height; y++)
        for (int x = 0; x < width; x++)
        {
            int i = y * width + x;

            vertices[i] = new Vector3(
                (x + 0.5f - width * 0.5f) * pixelSize,
                (y + 0.5f - height * 0.5f) * pixelSize,
                0);

            uvs[i] = new Vector2(
                (x + 0.5f) / width,
                (y + 0.5f) / height);

            indices[i] = i;
        }

        var mesh = new Mesh
        {
            indexFormat = count > 65535
                ? IndexFormat.UInt32
                : IndexFormat.UInt16
        };

        mesh.vertices = vertices;
        mesh.uv = uvs;
        mesh.SetIndices(indices, MeshTopology.Points, 0, false);

        float depth = pixelSize * Mathf.Max(0, extrusion);

        // Include the geometry generated by the shader.
        mesh.bounds = new Bounds(
            new Vector3(0, 0, depth * 0.5f),
            new Vector3(
                width * pixelSize,
                height * pixelSize,
                Mathf.Max(depth, 0.001f)));

        return mesh;
    }
}
```

