    string getPermutation(int n, int k) {
        vector<int> fact(n + 1, 1);
        for (int i = 1; i <= n; ++i) {
            fact[i] = fact[i - 1] * i;
        }

        string remaining;
        for (int i = 1; i <= n; ++i) {
            remaining.push_back('0' + i);
        }

        --k;
        string ans;
        for (int m = n; m >= 1; --m) {
            int index = k / fact[m - 1];
            ans.push_back(remaining[index]);
            remaining.erase(index, 1);
            k %= fact[m - 1];
        }
        return ans;
    }
};
```

时间复杂度为 **O(n²)**，因为删除字符需要移动后续字符；空间复杂度为 **O(n)**。在 `n <= 9` 的限制下，阶乘不会超出 `int` 范围，数字也均可用单个字符表示。

