  constructor(private readonly request: APIRequestContext) {}

  async create(input: CreateUserInput): Promise<string> {
    const response = await this.request.post("/users/v2/create", {
      data: input,
    });

    if (response.status() !== 201) {
      throw new Error(`Create user failed: HTTP ${response.status()}`);
    }

    return requireString(await response.json(), "id");
  }

  async setRole(
    id: string,
    role: "admin" | "user",
  ): Promise<Credentials> {
    const response = await this.request.post("/users/v2/permissions", {
      data: { id, role },
    });

    if (response.status() !== 200) {
      throw new Error(`Set permissions failed: HTTP ${response.status()}`);
    }

    const body: unknown = await response.json();
    return {
      username: requireString(body, "username"),
      password: requireString(body, "password"),
    };
  }

  async delete(id: string): Promise<void> {
    // Illustrative endpoint; adapt to your API contract.
    const response = await this.request.delete(
      `/users/v2/${encodeURIComponent(id)}`,
    );

    // A CRUD test might already have deleted the user.
    if (![204, 404].includes(response.status())) {
      throw new Error(`Delete user failed: HTTP ${response.status()}`);
    }
  }
}

// Facade: coordinates dependent API calls and tracks test-owned resources.
export class UserProvisioner {
  private readonly ids = new Set<string>();

  constructor(private readonly gateway: UserGateway) {}

  async createAdmin(
    input: CreateUserInput,
  ): Promise<Credentials & { id: string }> {
    const id = await this.gateway.create(input);
    this.ids.add(id); // Track before any subsequent setup can fail.

    const credentials = await this.gateway.setRole(id, "admin");
    return { id, ...credentials };
  }

  async cleanup(): Promise<void> {
    const results = await Promise.allSettled(
      [...this.ids].map(async (id) => {
        await this.gateway.delete(id);
        this.ids.delete(id);
      }),
    );

    const errors = results.flatMap((result) =>
      result.status === "rejected" ? [result.reason] : [],
    );

    if (errors.length) {
      throw new AggregateError(errors, "User cleanup failed");
    }
  }
}
