## My answer to the prompt

Use an **API adapter** for HTTP details, a **provisioning service / facade** for the multi-call workflow, and a **test-scoped Playwright fixture** for dependency injection and cleanup. Keep browser interactions in the page object.

The example below assumes string IDs, an `ADMIN` permission, and a delete endpoint. Adjust those contracts to your API.

```typescript
// support/users.ts
import {
  expect,
  type APIRequestContext,
} from "@playwright/test";

export interface CreateUserInput {
  username: string;
  email: string;
}

export interface Credentials {
  username: string;
  password: string;
}

export interface TestUser extends Credentials {
  id: string;
}

// The workflow depends on this contract, not on Playwright.
export interface UserApi {
  create(input: CreateUserInput): Promise<string>;
  setPermissions(id: string, permissions: string[]): Promise<Credentials>;
  delete(id: string): Promise<void>;
}

export class PlaywrightUserApi implements UserApi {
  constructor(private readonly request: APIRequestContext) {}

  async create(input: CreateUserInput): Promise<string> {
    const response = await this.request.post("/users/v2/create", {
      data: input,
    });

    expect(response.status(), "Create user").toBe(201);

    const body: unknown = await response.json();
    if (
      typeof body !== "object" ||
      body === null ||
      !("id" in body) ||
      typeof body.id !== "string" ||
      body.id.length === 0
    ) {
      throw new Error("Create user response must contain a nonempty string ID");
    }

    return body.id;
  }

  async setPermissions(
    id: string,
    permissions: string[],
  ): Promise<Credentials> {
    const response = await this.request.post("/users/v2/permissions", {
      data: { id, permissions },
    });

    expect(response.status(), "Set permissions").toBe(200);

    const body: unknown = await response.json();
    if (
      typeof body !== "object" ||
      body === null ||
      !("username" in body) ||
      typeof body.username !== "string" ||
      !("password" in body) ||
      typeof body.password !== "string"
    ) {
      throw new Error("Permission response must contain credentials");
    }

    return { username: body.username, password: body.password };
  }

  async delete(id: string): Promise<void> {
    const response = await this.request.delete(
      `/users/v2/${encodeURIComponent(id)}`,
    );

    // A delete test may already have removed the resource.
    expect([204, 404], "Delete test user").toContain(response.status());
  }
}

export class UserProvisioner {
  constructor(
    private readonly api: UserApi,
    private readonly registerForCleanup: (id: string) => void,
  ) {}

  async createAdmin(input: CreateUserInput): Promise<TestUser> {
    const id = await this.api.create(input);

    // Register before subsequent calls: they may fail.
    this.registerForCleanup(id);

    const credentials = await this.api.setPermissions(id, ["ADMIN"]);
    return { id, ...credentials };
  }
}
```

The fixture owns resource lifetime. It also attempts every deletion rather than stopping after the first cleanup failure.

