### 2. Recording service

```swift
import AVFoundation
import Foundation

enum RecorderError: LocalizedError {
    case permissionDenied
    case cannotStart
    case notRecording

    var errorDescription: String? {
        switch self {
        case .permissionDenied:
            return "Enable microphone access in Settings to record."
        case .cannotStart:
            return "The recording could not start."
        case .notRecording:
            return "There is no active recording."
        }
    }
}

@MainActor
protocol RecordingService: AnyObject {
    var onFailure: ((String) -> Void)? { get set }

    func start() throws
    func stop() throws -> URL
    func level() -> Float
}

@MainActor
final class AudioRecordingService: NSObject, RecordingService {
    var onFailure: ((String) -> Void)?

    private let session = AVAudioSession.sharedInstance()
    private var recorder: AVAudioRecorder?

    func start() throws {
        guard recorder == nil else {
            throw RecorderError.cannotStart
        }

        let directory = try FileManager.default.url(
            for: .documentDirectory,
            in: .userDomainMask,
            appropriateFor: nil,
            create: true
        ).appendingPathComponent("Recordings", isDirectory: true)

        try FileManager.default.createDirectory(
            at: directory,
            withIntermediateDirectories: true
        )

        let url = directory.appendingPathComponent(
            "\(UUID().uuidString).m4a"
        )

        do {
            try session.setCategory(.record, mode: .default)
            try session.setActive(true)

            let newRecorder = try AVAudioRecorder(
                url: url,
                settings: [
                    AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                    AVSampleRateKey: 44_100.0,
                    AVNumberOfChannelsKey: 1,
                    AVEncoderBitRateKey: 96_000
                ]
            )

            recorder = newRecorder
            newRecorder.delegate = self
            newRecorder.isMeteringEnabled = true

            guard newRecorder.prepareToRecord(),
                  newRecorder.record() else {
                throw RecorderError.cannotStart
            }
        } catch {
            discard()
            try? FileManager.default.removeItem(at: url)
            throw error
        }
    }

    func stop() throws -> URL {
        guard let recorder else {
            throw RecorderError.notRecording
        }

        let url = recorder.url
        recorder.delegate = nil
        recorder.stop()
        self.recorder = nil
        deactivate()

        return url
    }

    func level() -> Float {
        guard let recorder, recorder.isRecording else {
            return 0
        }

        recorder.updateMeters()
        let db = recorder.averagePower(forChannel: 0)

        // Display mapping, not a calibrated loudness measurement.
        return min(1, max(0, (db + 60) / 60))
    }

    private func deactivate() {
        try? session.setActive(
            false,
            options: .notifyOthersOnDeactivation
        )
    }

    private func discard() {
        let url = recorder?.url
        recorder?.delegate = nil
        recorder?.stop()
        recorder = nil
        deactivate()

        if let url {
            try? FileManager.default.removeItem(at: url)
        }
    }

    private func handleFailure(
        id: ObjectIdentifier,
        message: String
    ) {
        guard let recorder,
              ObjectIdentifier(recorder) == id else {
            return
        }

        discard()
        onFailure?(message)
    }
}

extension AudioRecordingService: AVAudioRecorderDelegate {
    nonisolated func audioRecorderEncodeErrorDidOccur(
        _ recorder: AVAudioRecorder,
        error: (any Error)?
    ) {
        let id = ObjectIdentifier(recorder)
        let message = error?.localizedDescription
            ?? "Audio encoding failed."

        Task { @MainActor [weak self] in
            self?.handleFailure(id: id, message: message)
        }
    }

    nonisolated func audioRecorderDidFinishRecording(
        _ recorder: AVAudioRecorder,
        successfully flag: Bool
    ) {
        guard !flag else { return }
        let id = ObjectIdentifier(recorder)

        Task { @MainActor [weak self] in
            self?.handleFailure(
                id: id,
                message: "Recording could not finish successfully."
            )
        }
    }
}
```

### 3. View model

Permission preparation has its own state, preventing repeated Start taps. Meter updates and UI state changes run on the main actor.

```swift
import AVFoundation
import Combine
import Foundation

@MainActor
final class RecorderViewModel: ObservableObject {
    enum State {
        case idle, preparing, recording
    }

    @Published private(set) var state: State = .idle
    @Published private(set) var levels =
        Array(repeating: Float.zero, count: 30)
    @Published private(set) var savedURL: URL?
    @Published private(set) var message: String?

    private let service: any RecordingService
    private var preparation: Task<Void, Never>?
    private var metering: Task<Void, Never>?

    init(service: any RecordingService) {
        self.service = service

        service.onFailure = { [weak self] message in
            guard let self else { return }
            metering?.cancel()
            metering = nil
            state = .idle
            self.message = message
        }
    }

    func start() {
        guard state == .idle else { return }

        state = .preparing
        message = nil
        savedURL = nil
        levels = Array(repeating: 0, count: levels.count)

        preparation = Task { @MainActor [weak self] in
            let allowed = await AVAudioApplication.requestRecordPermission()

            guard !Task.isCancelled, let self else { return }

            do {
                guard allowed else {
                    throw RecorderError.permissionDenied
                }

                // No suspension between starting the service and updating state.
                try service.start()
                state = .recording
                beginMetering()
            } catch {
                state = .idle
                message = error.localizedDescription
            }

            preparation = nil
        }
    }

    func stop(note: String? = nil) {
        preparation?.cancel()
        preparation = nil

        guard state == .recording else {
            state = .idle
            return
        }

        metering?.cancel()
        metering = nil

        do {
            savedURL = try service.stop()
            message = note ?? "Recording saved."
        } catch {
            message = error.localizedDescription
        }

        state = .idle
    }

    private func beginMetering() {
        metering?.cancel()

        metering = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                self?.sample()

                do {
                    try await Task.sleep(for: .milliseconds(50))
                } catch {
                    return
                }
            }
        }
    }

    private func sample() {
        guard state == .recording else { return }
        levels.removeFirst()
        levels.append(service.level())
    }
}
```

