The following can live in one Swift file initially; split the service, view model, and view into separate files as the project grows.

```swift
import SwiftUI
import AVFoundation
import Combine

enum RecordingError: LocalizedError {
    case permissionDenied
    case cannotStart
    case noRecording

    var errorDescription: String? {
        switch self {
        case .permissionDenied:
            return "Enable microphone access for this app in Settings."
        case .cannotStart:
            return "The recording could not start."
        case .noRecording:
            return "There is no active recording to save."
        }
    }
}

@MainActor
protocol RecordingService: AnyObject {
    func start() throws
    func stop() throws -> URL
    func level() -> Float
}

@MainActor
final class LocalRecordingService: RecordingService {
    private let session = AVAudioSession.sharedInstance()
    private var recorder: AVAudioRecorder?

    func start() throws {
        guard recorder == nil else {
            throw RecordingError.cannotStart
        }

        var pendingURL: URL?

        do {
            try session.setCategory(.record, mode: .default)
            try session.setActive(true)

            let directory = try FileManager.default.url(
                for: .documentDirectory,
                in: .userDomainMask,
                appropriateFor: nil,
                create: true
            ).appendingPathComponent("Recordings", isDirectory: true)

            try FileManager.default.createDirectory(
                at: directory,
                withIntermediateDirectories: true
            )

            let url = directory.appendingPathComponent(
                "\(UUID().uuidString).m4a"
            )
            pendingURL = url

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100.0,
                AVNumberOfChannelsKey: 1,
                AVEncoderBitRateKey: 128_000
            ]

            let candidate = try AVAudioRecorder(
                url: url,
                settings: settings
            )
            candidate.isMeteringEnabled = true

            guard candidate.prepareToRecord(), candidate.record() else {
                candidate.stop()
                throw RecordingError.cannotStart
            }

            recorder = candidate
        } catch {
            if let pendingURL {
                try? FileManager.default.removeItem(at: pendingURL)
            }
            try? session.setActive(
                false,
                options: .notifyOthersOnDeactivation
            )
            throw error
        }
    }

    func stop() throws -> URL {
        guard let recorder else {
            throw RecordingError.noRecording
        }

        let url = recorder.url
        let duration = recorder.currentTime

        recorder.stop()
        self.recorder = nil

        try? session.setActive(
            false,
            options: .notifyOthersOnDeactivation
        )

        guard duration > 0,
              FileManager.default.fileExists(atPath: url.path) else {
            try? FileManager.default.removeItem(at: url)
            throw RecordingError.noRecording
        }

        return url
    }

    func level() -> Float {
        guard let recorder, recorder.isRecording else {
            return 0
        }

        recorder.updateMeters()
        let db = recorder.averagePower(forChannel: 0)

        // Display mapping, not a calibrated loudness measurement.
        return min(1, max(0, (db + 60) / 60))
    }
}

